@page "/profile"
@using Microsoft.AspNetCore.Components.Authorization
@rendermode InteractiveAuto
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Profile</PageTitle>

<h1>Profile</h1>

@if (_name is not null)
{
    <p><strong>Name:</strong> @_name</p>
    <h3>Roles</h3>
    <ul>
        @foreach (var role in _roles)
        {
            <li>@role</li>
        }
    </ul>
}
else
{
    <p>Not authenticated.</p>
}

@code {
    private string? _name;
    private string[] _roles = [];

    protected override async Task OnInitializedAsync()
    {
        var state = await AuthStateProvider.GetAuthenticationStateAsync();
        var user = state.User;

        if (user.Identity?.IsAuthenticated == true)
        {
            _name = user.Identity.Name;
            _roles = user.FindAll(System.Security.Claims.ClaimTypes.Role)
                         .Select(c => c.Value)
                         .ToArray();
        }
    }
}

@page "/editor"
@using Microsoft.AspNetCore.Components.Authorization
@rendermode InteractiveAuto
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Editor</PageTitle>

<h1>Editor</h1>

@if (_isAuthorized)
{
    <p>Welcome to the Editor area!</p>
}
else
{
    <p><strong>Access denied.</strong> You do not have the required "Editor" role.</p>
}

@code {
    private bool _isAuthorized;

    protected override async Task OnInitializedAsync()
    {
        var state = await AuthStateProvider.GetAuthenticationStateAsync();
        _isAuthorized = state.User.IsInRole("Editor");
    }
}

@page "/viewer"
@using Microsoft.AspNetCore.Components.Authorization
@rendermode InteractiveAuto
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Viewer</PageTitle>

<h1>Viewer</h1>

@if (_isAuthenticated)
{
    <p>Welcome, @_name! You are authenticated.</p>
}
else
{
    <p><strong>Access denied.</strong> You must be authenticated to view this page.</p>
}

@code {
    private bool _isAuthenticated;
    private string? _name;

    protected override async Task OnInitializedAsync()
    {
        var state = await AuthStateProvider.GetAuthenticationStateAsync();
        _isAuthenticated = state.User.Identity?.IsAuthenticated == true;
        _name = state.User.Identity?.Name;
    }
}

